# -*- coding: utf-8 -*-
"""Nội dung mới của Chương 2 (sau tái cấu trúc).

Mỗi phần tử của BLOCKS là một tuple:
  ('h2', idx_goc, 'tiêu đề mới')   -> giữ đoạn Heading 2 gốc (bookmark, paraId), đổi chữ
  ('h3', idx_goc, 'tiêu đề mới')   -> giữ đoạn Heading 3 gốc, đổi chữ
  ('p',  'văn bản')                -> đoạn mới, style "Nội dung" (176); **...** là chữ đậm
  ('p177', 'văn bản')              -> đoạn mới, style "Nội dung sau bảng" (177)
  ('orig', idx_goc)                -> chuyển nguyên phần tử gốc (chú thích bảng, bảng)
idx_goc là chỉ số phần tử con của <w:body> trong tệp gốc.
"""

CH2_FIRST = 300   # phần tử đầu tiên sau tiêu đề chương 2
CH2_LAST = 377    # bảng 2.4 (phần tử cuối của chương 2)

BLOCKS = [
    ('p', 'Chương này trình bày các cơ sở lý thuyết làm nền tảng cho việc thiết kế và đánh giá hệ thống, lần lượt từ bài toán nghiệp vụ đến kiến trúc, bảo mật, dữ liệu, phương pháp phát triển và yêu cầu đối với thông tin hiển thị cho người dùng (các mục 2.1–2.6). Trên nền đó, mục 2.7 khảo sát các công trình liên quan để xác định vị trí của đề tài, còn mục 2.8 giới thiệu các công nghệ được lựa chọn cùng căn cứ lựa chọn.'),

    # ------------------------------------------------------------------ 2.1
    ('h2', 301, 'Hệ thống thông tin quản lý nông trại và đặc thù nông hộ quy mô nhỏ'),
    ('p', 'Hệ thống thông tin quản lý nông trại (FMIS) là hệ thống thu thập, xử lý, lưu trữ và phân phối dữ liệu cần thiết cho việc điều hành các hoạt động của nông trại [3]. Vì dữ liệu được ghi lại nhằm phục vụ việc điều hành, các chức năng thường gặp của một FMIS xoay quanh bốn nhóm: lập kế hoạch sản xuất, ghi nhật ký thực hiện công việc, quản lý vật tư và quản lý tài chính. Phạm vi chức năng của từng hệ thống trong thực tế lại rất khác nhau; một tổng quan tài liệu có hệ thống đã ghi nhận sự khác biệt này, đồng thời xác định các đặc tính cần có của một FMIS như khả năng ghi chép thuận tiện, báo cáo và tích hợp dữ liệu [4]. Về mặt kiến trúc, một FMIS hiện đại thường được xem là một thành phần trong hệ sinh thái phần mềm nông nghiệp, trao đổi dữ liệu với nhiều bên liên quan [9].'),
    ('p', 'Đối với nông hộ quy mô nhỏ, việc tiếp cận các hệ thống như vậy gặp những rào cản riêng, phổ biến là chi phí, độ phức tạp và khả năng sử dụng [4]. Cùng hướng với nhận định này, mô hình khái niệm FMIS cho nông hộ nhỏ được đề xuất trong nghiên cứu về nông hộ trồng ớt tại Indonesia nhấn mạnh sự cần thiết của một hệ thống đơn giản, tập trung vào những chức năng cốt lõi [5]. Điều kiện hạ tầng cũng thuộc về bài toán: ở khu vực nông thôn, kết nối còn hạn chế và là một ràng buộc thiết kế quan trọng [1].'),
    ('p', 'Những đặc thù này dẫn tới ba định hướng của AgriLog V2. Thứ nhất, giao diện phải đơn giản và dùng được trên thiết bị di động, vì độ phức tạp và khả năng sử dụng là những rào cản đã được chỉ ra. Thứ hai, hệ thống phải vận hành được khi mất kết nối, vì dữ liệu phát sinh tại ruộng vườn, nơi không phải lúc nào cũng có mạng. Thứ ba, dữ liệu phải có cấu trúc để hoạt động canh tác, vật tư và các khoản thu – chi liên hệ được với nhau, từ đó tổng hợp được chi phí theo lô. Định hướng thứ hai là lý do của kiến trúc ưu tiên ngoại tuyến trình bày ở mục 2.2; định hướng thứ ba đặt ra yêu cầu đối với mô hình dữ liệu và giao dịch ở mục 2.4.'),

    # ------------------------------------------------------------------ 2.2
    ('h2', 306, 'Kiến trúc ưu tiên ngoại tuyến và đồng bộ dữ liệu'),
    ('p', 'Điện toán di động đối mặt với những thách thức cố hữu như chất lượng mạng biến động khó đoán, kết nối gián đoạn và tài nguyên thiết bị hạn chế; khả năng tiếp tục hoạt động khi mất kết nối (disconnected operation) vì thế là yêu cầu cơ bản của loại ứng dụng này [6]. Hướng tiếp cận ưu tiên cục bộ (local-first) đáp ứng yêu cầu đó bằng cách đổi vai trò của hai phía: bản sao dữ liệu chính nằm trên thiết bị của người dùng, còn máy chủ đóng vai trò đồng bộ và sao lưu thay vì là điều kiện để ứng dụng hoạt động [7]. Kiến trúc ưu tiên ngoại tuyến (offline-first) của đề tài vận dụng nguyên lý này: ứng dụng đọc và ghi trên cơ sở dữ liệu cục bộ trước, việc trao đổi với máy chủ được thực hiện khi có kết nối.'),
    ('p', 'Hệ quả trực tiếp là mỗi thao tác ghi có hai thời điểm khác nhau: thời điểm dữ liệu được lưu trên thiết bị và thời điểm thay đổi đó được máy chủ xác nhận. Trong khoảng giữa hai thời điểm, trạng thái cục bộ phải được hiểu là dữ liệu đang chờ trao đổi, không phải dữ liệu đã được máy chủ lưu thành công. Sự phân biệt này chi phối cả giao thức đồng bộ lẫn cách giao diện trình bày trạng thái dữ liệu cho người dùng (các mục 3.3 và 3.7).'),
    ('p', 'Cho phép ghi khi không liên lạc được với máy chủ là một lựa chọn về mô hình nhất quán, và định lý CAP cho thấy lựa chọn này có cái giá của nó. Theo định lý, một hệ thống dữ liệu phân tán không thể đồng thời bảo đảm cả ba tính chất nhất quán (consistency), sẵn sàng (availability) và chịu phân vùng mạng (partition tolerance); khi mạng bị chia cắt, hệ thống không thể vừa nhất quán vừa sẵn sàng. Định lý được Gilbert và Lynch chứng minh hình thức [10] và được Brewer phân tích lại với góc nhìn thực dụng hơn [11]. Thiết bị mất kết nối với máy chủ là một trường hợp phân vùng, và ứng dụng ưu tiên ngoại tuyến chọn tính sẵn sàng: thao tác ghi cục bộ vẫn được chấp nhận, đổi lại các bản sao chỉ hội tụ sau một khoảng thời gian. Mô hình nhất quán cuối cùng (eventual consistency) mô tả đúng hành vi này: nếu không có thay đổi mới, mọi bản sao cuối cùng sẽ có cùng giá trị [12].'),
    ('p', 'Chấp nhận nhất quán cuối cùng cũng là chấp nhận khả năng xung đột: khi nhiều bản sao cùng được sửa độc lập trong lúc chưa đồng bộ, hệ thống phải quyết định thay đổi nào được giữ lại. Hệ thống Bayou đặt vấn đề này trong môi trường lưu trữ nhân bản kết nối yếu và đề xuất phát hiện, giải quyết xung đột theo ngữ nghĩa của ứng dụng [13]. Một chiến lược đơn giản hơn là last-write-wins (LWW – bản ghi sau cùng thắng), dựa trên việc sắp xếp các sự kiện theo dấu thời gian. Giới hạn của chiến lược này nằm ở chính dấu thời gian: thứ tự theo đồng hồ vật lý chỉ là thứ tự gần đúng vì đồng hồ của các thiết bị không hoàn toàn đồng bộ [14], nên kết quả phân xử có thể phụ thuộc vào độ lệch đồng hồ giữa các thiết bị. Ở hướng ngược lại, các kiểu dữ liệu nhân bản không xung đột (CRDT) được thiết kế để các bản sao hội tụ mà không cần phân xử tập trung [15], nhưng đòi hỏi mô hình dữ liệu và thuật toán phức tạp hơn.'),
    ('p', 'Việc lựa chọn giữa các chiến lược vì vậy phụ thuộc vào mức độ mà dữ liệu bị nhiều bản sao sửa đồng thời. Với AgriLog V2, dữ liệu của mỗi nông hộ chủ yếu do một người dùng trên một thiết bị chỉnh sửa, nên khả năng hai bản sao cùng sửa một bản ghi là thấp. Nhóm chọn last-write-wins kết hợp quy tắc xóa thắng sửa vì dễ giải thích với người dùng và dễ kiểm thử, đồng thời bổ sung cơ chế trả bản ghi bị từ chối kèm lý do để việc loại bỏ một thay đổi không diễn ra âm thầm. Giao thức đồng bộ và các tình huống xung đột cụ thể được thiết kế ở mục 3.3.'),

    # ------------------------------------------------------------------ 2.3
    ('h2', 314, 'Dịch vụ REST, xác thực và kiểm soát truy cập'),
    ('p', 'Ứng dụng di động và trang quản trị trao đổi dữ liệu với máy chủ thông qua các dịch vụ web theo phong cách REST. REST (Representational State Transfer) là một phong cách kiến trúc cho hệ thống siêu phương tiện phân tán, được định nghĩa bằng một tập ràng buộc: tách biệt client–server, không lưu trạng thái phiên trên máy chủ (stateless), cho phép bộ nhớ đệm, giao diện thống nhất và hệ thống phân tầng [16]. Trong các ràng buộc này, tính không trạng thái ảnh hưởng trực tiếp nhất đến thiết kế của đề tài: mỗi yêu cầu phải mang đủ thông tin để máy chủ xử lý, nhờ đó dịch vụ dễ mở rộng ngang và dễ kiểm thử. Giao thức đồng bộ và các điểm cuối nghiệp vụ của AgriLog V2 được thiết kế theo phong cách này. Hệ quả kéo theo là máy chủ không dựa vào phiên đã lưu để nhận biết người gọi, nên danh tính phải đi cùng từng yêu cầu.'),
    ('p', 'JSON Web Token (JWT) đáp ứng đúng yêu cầu đó. JWT là mã đăng nhập có chữ ký, mang thông tin định danh của người dùng và thời hạn hiệu lực; máy chủ xác minh chữ ký mà không cần lưu phiên, phù hợp với dịch vụ RESTful không trạng thái [17]. Độ an toàn của cơ chế này phụ thuộc vào cách sử dụng: các nghiên cứu về lược đồ xác thực dựa trên JWT chỉ ra những lưu ý như bảo vệ khóa ký và đặt thời hạn mã hợp lý [18]. Trong AgriLog V2, JWT là cơ chế xác thực duy nhất cho các điểm cuối cần bảo vệ; riêng thời hạn mã còn phải tính đến việc thiết bị của nông hộ có thể không liên lạc được với máy chủ trong nhiều ngày (mục 3.5.2).'),
    ('p', 'Xác thực mới trả lời câu hỏi người gọi là ai; việc người đó được phép làm gì thuộc về kiểm soát truy cập. Mô hình kiểm soát truy cập theo vai trò (Role-Based Access Control – RBAC) gán quyền cho vai trò thay vì gán trực tiếp cho từng người dùng; người dùng được cấp quyền thông qua vai trò của mình [19]. Cách tiếp cận này đơn giản hóa quản trị phân quyền khi hệ thống có nhiều người dùng cùng nhóm, và AgriLog V2 sử dụng hai vai trò là quản trị viên và nông hộ. Tuy nhiên, vai trò chỉ phân biệt được loại thao tác mà một nhóm người dùng được thực hiện, không phân biệt được dữ liệu của nông hộ này với dữ liệu của nông hộ khác. RBAC vì thế được kết hợp với kiểm tra quyền sở hữu trên từng bản ghi.'),
    ('p', 'Yêu cầu về quyền sở hữu xuất phát từ đặc điểm của cơ sở dữ liệu dùng chung cho nhiều người dùng (multi-tenant): dữ liệu của mỗi người dùng phải được cô lập và kiểm soát truy cập ở mọi đường truy cập đến dữ liệu [20]. Điều kiện “mọi đường truy cập” có ý nghĩa thực tế, bởi giao diện người dùng không phải là ranh giới bảo mật: nghiên cứu về các giao diện lập trình của ứng dụng di động cho thấy sự không nhất quán giữa phần kiểm tra ở ứng dụng và phần kiểm tra ở máy chủ có thể dẫn đến lỗ hổng [21]. Từ đây có ba nguyên tắc được áp dụng cho thiết kế phân quyền ở mục 3.5. Một là, danh tính được xác minh từ mã đăng nhập đã ký, và thông tin định danh lấy từ ngữ cảnh xác thực thay vì từ dữ liệu do máy khách gửi lên. Hai là, quyền theo vai trò và quyền sở hữu đều phải được kiểm tra tại máy chủ. Ba là, việc kiểm tra áp dụng cho cả điểm cuối REST lẫn đường đồng bộ, vì đây là hai đường cùng dẫn đến một dữ liệu.'),

    # ------------------------------------------------------------------ 2.4
    ('h2', 323, 'Cơ sở dữ liệu, giao dịch và tính toán số tiền'),
    ('p', 'Dữ liệu sổ sách của nông hộ gồm nhiều loại bản ghi có quan hệ chặt với nhau, nên đề tài tổ chức dữ liệu theo mô hình quan hệ. Mô hình này biểu diễn dữ liệu dưới dạng các quan hệ (bảng) và cho phép truy vấn độc lập với cách lưu trữ vật lý [22]. Để đi từ nghiệp vụ đến các bảng, mô hình thực thể – liên kết (ER) mô tả thế giới thực bằng các thực thể, thuộc tính và mối liên kết, và thường được dùng để thiết kế cơ sở dữ liệu quan hệ trước khi cài đặt [23]. Lược đồ cơ sở dữ liệu của AgriLog V2 được xây dựng theo đúng trình tự đó: thiết kế theo mô hình ER, sau đó cài đặt thành 16 bảng quan hệ (mục 3.4).'),
    ('p', 'Khi dữ liệu được cập nhật, tính toàn vẹn được bảo đảm bằng giao dịch: một đơn vị công việc phải thỏa các tính chất nguyên tử (atomicity), nhất quán (consistency), cô lập (isolation) và bền vững (durability), thường được viết tắt là ACID [24]. Trong bốn tính chất, tính nguyên tử liên quan trực tiếp nhất đến đồng bộ dữ liệu, vì nó bảo đảm một lô thao tác hoặc được thực hiện trọn vẹn, hoặc không thực hiện phần nào. Một lô thay đổi gửi từ thiết bị được xử lý như một giao dịch, nên việc gửi lại sau lỗi không để lại dữ liệu ghi dở (mục 3.3.3).'),
    ('p', 'Với các khoản thu – chi, tính đúng đắn còn phụ thuộc vào cách biểu diễn và làm tròn số tiền. Số thực dấu phẩy động nhị phân không biểu diễn chính xác mọi giá trị thập phân và có thể sinh sai số làm tròn [25]. Bản thân quy tắc làm tròn cũng không thống nhất giữa các môi trường thực thi. Chuẩn IEEE 754 quy định chế độ làm tròn mặc định là làm tròn đến giá trị gần nhất, hòa thì về số chẵn (roundTiesToEven) [26]; hàm round của Python hành xử theo cách này, trong khi hàm Math.round của JavaScript làm tròn nửa lên. Khi cùng một phép tính tiền được thực hiện ở hai ngôn ngữ, sự khác biệt này có thể gây lệch một đồng.'),
    ('p', 'Đối với AgriLog V2, đây là vấn đề của kiến trúc chứ không chỉ của cách cài đặt: các quy tắc nghiệp vụ cần chạy ngoại tuyến được viết ở cả máy chủ và ứng dụng di động, nên cùng một dữ liệu phải cho cùng một kết quả ở hai phía. Hệ thống do đó cần một quy tắc làm tròn thống nhất và được kiểm thử ở cả hai phía; quy ước lưu số tiền và mô-đun làm tròn dùng chung được trình bày ở các mục 3.3.5 và 4.2.2.'),

    # ------------------------------------------------------------------ 2.5
    ('h2', 330, 'Quy trình phát triển phần mềm, đặc tả yêu cầu và kiểm thử'),
    ('p', 'Các bước phân tích, thiết kế và kiểm thử ở Chương 3 và Chương 4 dựa trên một số mô hình và tiêu chuẩn của công nghệ phần mềm, được trình bày dưới đây theo tiến trình phát triển. Về quy trình, mô hình thác nước (waterfall) chia phát triển thành các giai đoạn tuần tự từ yêu cầu, thiết kế, cài đặt đến kiểm thử [27], phù hợp khi yêu cầu ổn định. Mô hình xoắn ốc kết hợp tính lặp của mô hình nguyên mẫu với tính hệ thống của mô hình thác nước và lấy phân tích rủi ro làm trục điều khiển [8]. Do yêu cầu của AgriLog V2 được làm rõ dần qua từng giai đoạn, đề tài áp dụng cách tiếp cận lặp: mỗi giai đoạn gồm phân tích, thiết kế, cài đặt và kiểm thử cho một nhóm chức năng.'),
    ('p', 'Ở bước xác định yêu cầu, tiêu chuẩn ISO/IEC/IEEE 29148 hướng dẫn quá trình kỹ nghệ yêu cầu, trong đó yêu cầu cần được phát biểu rõ ràng, có thể kiểm chứng và truy vết được [28]; yêu cầu thường được phân thành yêu cầu chức năng và yêu cầu phi chức năng. Ở bước thiết kế, tiêu chuẩn IEEE 1016 quy định nội dung của tài liệu mô tả thiết kế phần mềm, trong đó có các góc nhìn về ngữ cảnh, thành phần, dữ liệu, giao diện và hành vi [29]. Ngôn ngữ mô hình hóa thống nhất (UML) cung cấp các biểu đồ tương ứng: biểu đồ use case biểu diễn tương tác giữa tác nhân và hệ thống, biểu đồ tuần tự biểu diễn thứ tự thông điệp giữa các thành phần theo thời gian. Chương 3 áp dụng các khái niệm này: yêu cầu phi chức năng được phát biểu kèm cách kiểm chứng (mục 3.1.3), còn các luồng xử lý chính được mô hình hóa bằng biểu đồ use case và biểu đồ tuần tự (mục 3.2).'),
    ('p', 'Kiểm thử phần mềm là quá trình thực thi hệ thống nhằm kiểm tra sự phù hợp với yêu cầu và phát hiện lỗi; tiêu chuẩn ISO/IEC/IEEE 29119-1 định nghĩa các khái niệm nền tảng như mức kiểm thử, kỹ thuật kiểm thử và chiến lược kiểm thử [30]. Để định lượng mức độ kiểm thử, chỉ số thường dùng là độ phủ (coverage), đo tỷ lệ mã được thực thi bởi bộ kiểm thử. Chỉ số này cần được diễn giải thận trọng: nghiên cứu thực nghiệm cho thấy độ phủ chỉ có tương quan thấp đến vừa với khả năng phát hiện lỗi của bộ kiểm thử khi đã loại trừ ảnh hưởng của kích thước bộ kiểm thử [31]. Vì vậy, báo cáo trình bày độ phủ cùng với số lượng bài kiểm thử, phạm vi nghiệp vụ và các lỗi thực tế đã phát hiện, không dùng độ phủ như bằng chứng duy nhất về chất lượng.'),
    ('p', 'Đối với hiệu năng, cách tóm tắt kết quả đo cũng quyết định độ tin cậy của kết luận. Độ trễ trung bình có thể che giấu những yêu cầu chậm bất thường; để mô tả trải nghiệm thực tế, cần xem các phân vị cao của phân bố độ trễ, chẳng hạn p95 hoặc p99 [32]. Phân vị p95 là giá trị mà 95% số yêu cầu có thời gian xử lý không vượt quá, còn 5% còn lại có thể chậm hơn. Một giá trị phân vị chỉ có ý nghĩa khi đi kèm cấu hình môi trường thử nghiệm và loại thao tác được đo, nên kết quả kiểm tải ở mục 4.5.4 được trình bày cùng các điều kiện này.'),

    # ------------------------------------------------------------------ 2.6
    ('h2', 339, 'Khả năng tiếp cận giao diện và minh bạch nguồn dữ liệu nông học'),
    ('p', 'Thông tin mà ứng dụng cung cấp chỉ có giá trị sử dụng khi người dùng đọc được nó và biết nó dựa trên căn cứ nào. Yêu cầu thứ nhất thuộc về hình thức trình bày, yêu cầu thứ hai thuộc về nội dung, và cả hai cùng quyết định mức độ người dùng có thể dựa vào ứng dụng. Về hình thức, hướng dẫn WCAG 2.1 đặt ra các tiêu chí giúp nội dung dễ tiếp cận hơn; riêng với độ tương phản màu, văn bản thông thường cần tỷ lệ tối thiểu 4,5:1 ở mức AA và 7:1 ở mức AAA [33]. Đề tài dùng tiêu chí này để kiểm tra độ tương phản của màu chữ trên giao diện di động. Kết quả đó là tự kiểm tra của nhóm theo một tiêu chí, không phải chứng nhận độc lập về WCAG cho toàn bộ ứng dụng.'),
    ('p', 'Về nội dung, dữ liệu nông học như thời gian sinh trưởng, định mức phân bón hay quy trình chăm sóc phụ thuộc giống, giai đoạn sinh trưởng và điều kiện canh tác; nếu không có nguồn, người dùng khó xác định phạm vi áp dụng. Khó khăn trong chia sẻ và thống nhất dữ liệu giữa các thành phần phần mềm cũng được nêu là một trở ngại của hệ sinh thái phần mềm nông nghiệp [9]. AgriLog V2 vì vậy gắn nguồn cho từng giống và quy trình, dựa trên các văn bản chính thống như Quyết định 1972/QĐ-UBND của UBND tỉnh Lâm Đồng [34] và Quyết định 254/QĐ-TT-CCN của Cục Trồng trọt [35], và hiển thị “Chưa có dữ liệu” khi thiếu căn cứ thay vì tự điền giá trị. Cũng như với độ tương phản, phạm vi của khẳng định cần được giữ đúng: liên kết nguồn cho biết thông tin được lấy từ đâu, không đồng nghĩa nội dung đã được thẩm định độc lập. Hai yêu cầu trên được cụ thể hóa thành các nguyên tắc thiết kế giao diện ở mục 3.7.1.'),

    # ------------------------------------------------------------------ 2.7
    ('h2', 344, 'Các công trình liên quan và định hướng của đề tài'),
    ('p', 'Các khái niệm ở những mục trên được rút ra từ nhiều công trình thuộc các hướng nghiên cứu khác nhau. Mục này xem xét lại các công trình đó theo một góc độ khác: mỗi hướng giải quyết vấn đề gì, còn để ngỏ điều gì đối với bài toán của đề tài và đề tài kế thừa được gì.'),
    ('h3', 345, 'Các hướng nghiên cứu và giải pháp liên quan'),
    ('p', 'Qua khảo sát tài liệu, các công trình liên quan đến đề tài có thể được phân thành bốn hướng.'),
    ('p', '1) **Tổng quan về hệ thống thông tin quản lý nông trại.** Fountas và cộng sự [3] tổng kết hiện trạng và triển vọng của FMIS, cho thấy các hệ thống ngày càng mở rộng từ ghi chép đơn thuần sang hỗ trợ ra quyết định. Tummers và cộng sự [4] thực hiện tổng quan tài liệu có hệ thống về các trở ngại và đặc tính của FMIS. Hai công trình cho biết một FMIS cần có những gì và gặp trở ngại nào khi đưa vào sử dụng, nhưng là công trình tổng quan nên không hướng tới một sản phẩm cụ thể cho nông hộ nhỏ. Đối với đề tài, chúng cung cấp khung chức năng tham chiếu để xác định phạm vi các phân hệ canh tác, vật tư và tài chính.'),
    ('p', '2) **FMIS cho nông hộ quy mô nhỏ.** Henriyadi và cộng sự [5] đề xuất mô hình khái niệm để phát triển FMIS cho nông hộ nhỏ, với trường hợp nông hộ trồng ớt tại Indonesia. Trong các công trình được khảo sát, đây là công trình có đối tượng gần với đề tài nhất, và là căn cứ cho định hướng giữ hệ thống đơn giản, tập trung vào chức năng cốt lõi. Công trình dừng ở mức mô hình khái niệm; các vấn đề cài đặt như vận hành ngoại tuyến và đồng bộ dữ liệu không phải trọng tâm.'),
    ('p', '3) **Kiến trúc và hạ tầng cho phần mềm nông nghiệp.** Kruize và cộng sự [9] đề xuất kiến trúc tham chiếu cho hệ sinh thái phần mềm nông trại, nhấn mạnh khả năng trao đổi dữ liệu giữa các thành phần. Ahmed và cộng sự [1] nghiên cứu giải pháp Internet vạn vật cho nông nghiệp ở vùng nông thôn, nơi hạ tầng kết nối là ràng buộc chính. Hai công trình tiếp cận ở tầng hệ sinh thái và hạ tầng, không đi vào ứng dụng ghi chép của từng nông hộ. Giá trị tham khảo đối với đề tài là hai ràng buộc thiết kế: dữ liệu dùng chung giữa các thành phần cần được thống nhất, và kết nối ở nông thôn không thể được giả định là luôn sẵn có.'),
    ('p', '4) **Phần mềm ưu tiên cục bộ và đồng bộ dữ liệu.** Kleppmann và cộng sự [7] nêu các nguyên tắc của phần mềm local-first, trong đó dữ liệu thuộc về thiết bị của người dùng; Terry và cộng sự [13] trình bày cách quản lý xung đột cập nhật trong hệ lưu trữ nhân bản kết nối yếu; Shapiro và cộng sự [15] đề xuất các kiểu dữ liệu nhân bản không xung đột. Các công trình này là nền tảng chung về kiến trúc và thuật toán, đã được vận dụng ở mục 2.2, nhưng không gắn với nghiệp vụ nông nghiệp; việc chọn chiến lược nào cho một ứng dụng cụ thể vẫn phải dựa trên đặc điểm dữ liệu của chính ứng dụng đó.'),
    ('p', 'Đặt bốn hướng cạnh nhau, trong phạm vi các công trình được khảo sát có thể thấy một khoảng cách. Các công trình về FMIS xác định nghiệp vụ và rào cản của nông hộ nhỏ nhưng không lấy vận hành ngoại tuyến làm trọng tâm; các công trình về phần mềm ưu tiên cục bộ giải quyết vận hành ngoại tuyến và đồng bộ nhưng không gắn với nghiệp vụ nông nghiệp. Bài toán của đề tài nằm ở phần giao của hai nhóm này.'),
    ('p', 'Ngoài các công trình học thuật, cần xét đến những cách ghi chép mà nông hộ đang dùng trong thực tế, thường là một trong ba cách: sổ giấy, bảng tính và ứng dụng trực tuyến. Bảng 2.1 đối chiếu các cách này theo đặc tính kỹ thuật; nhóm không gán tên hoặc tính năng cụ thể cho phần mềm thương mại khi chưa có kết quả khảo sát tương ứng.'),
    ('orig', 352),   # chú thích Bảng 2.1
    ('orig', 353),   # Bảng 2.1
    ('h3', 354, 'Đối chiếu và phạm vi đóng góp của đề tài'),
    ('p', 'Bảng 2.2 đối chiếu đề tài với các nhóm công trình đã khảo sát theo bảy tiêu chí, từ loại công trình và đối tượng đến cách kiểm chứng. Đây là so sánh theo phạm vi và đặc tính của công trình, không phải kết quả thử nghiệm so sánh hiệu năng; báo cáo không kết luận AgriLog V2 vượt trội một sản phẩm thương mại cụ thể.'),
    ('orig', 356),   # chú thích Bảng 2.2
    ('orig', 357),   # Bảng 2.2
    ('p177', 'Từ đối chiếu trên, điểm khác biệt của đề tài thể hiện ở hai mặt. Về nghiệp vụ, đề tài gộp lô đất, vụ trồng, công việc chăm sóc, vật tư và thu – chi của nông hộ vào một luồng dữ liệu thống nhất, gắn với dữ liệu nông học có nguồn. Về kỹ thuật, đề tài hiện thực một hệ thống ưu tiên ngoại tuyến cho bài toán này, trong đó đồng bộ, xử lý xung đột và phân quyền được thiết kế như các thành phần cốt lõi và được kiểm chứng bằng kiểm thử tự động. Đóng góp này mang tính vận dụng và tích hợp: đề tài không đề xuất thuật toán đồng bộ mới mà áp dụng các nguyên lý đã có vào một bài toán nghiệp vụ cụ thể, và các kết luận được giới hạn trong phạm vi kiểm chứng nêu ở mục 4.5.6.'),

    # ------------------------------------------------------------------ 2.8
    ('h2', 359, 'Công nghệ và công cụ được lựa chọn'),
    ('p', 'Mục này chỉ trình bày những công nghệ thực sự được sử dụng trong mã nguồn của hệ thống; phiên bản được đối chiếu với tệp khai báo phụ thuộc của từng phân hệ. Mỗi lựa chọn được xem xét theo vai trò trong kiến trúc, đặc điểm kỹ thuật liên quan đến yêu cầu của đề tài và phương án thay thế đã được cân nhắc.'),
    ('p', 'Ứng dụng di động được xây dựng bằng React Native 0.81 với React 19.1 và TypeScript 5.8; điều hướng dùng React Navigation 7. React Native thuộc nhóm tiếp cận đa nền tảng đã được khảo sát trong [36], cho phép xây dựng ứng dụng di động bằng một mã nguồn theo mô hình thành phần. So với phát triển bản địa bằng Kotlin hoặc Swift, lựa chọn này phù hợp với đề tài ở hai điểm: ứng dụng dùng chung ngôn ngữ và kiểu dữ liệu với trang quản trị, và các quy tắc nghiệp vụ ngoại tuyến chỉ cần viết một lần cho ứng dụng.'),
    ('p', 'Thành phần quyết định khả năng ngoại tuyến là lớp cơ sở dữ liệu cục bộ, do WatermelonDB 0.28 trên SQLite đảm nhiệm (lược đồ phiên bản 7 gồm 13 bảng). Thư viện này có hai đặc điểm khớp với kiến trúc ở mục 2.2: màn hình quan sát trực tiếp dữ liệu cục bộ nên tự cập nhật khi bản ghi thay đổi, và thư viện có sẵn khung đồng bộ kéo về/đẩy lên (pull/push). Phương án gọi API trực tiếp kèm lưu đệm khóa – giá trị không được chọn vì ứng dụng cần một cơ sở dữ liệu quan hệ cục bộ có truy vấn, quan sát thay đổi và khung đồng bộ; lưu đệm khóa – giá trị không đáp ứng được truy vấn theo lô và theo kỳ. Trong các thư viện hỗ trợ, react-native-keychain có vai trò về bảo mật vì giữ mã đăng nhập trong kho khóa của hệ điều hành; các thư viện phục vụ chọn và lưu tạm ảnh, video, phát video nhúng, xuất và chia sẻ báo cáo, vẽ biểu đồ được liệt kê ở Bảng 2.3.'),
    ('p', 'Ở phía máy chủ, dịch vụ REST [16] được xây dựng bằng FastAPI (trên Starlette, chạy bằng Uvicorn) và Pydantic 2. Pydantic kiểm tra kiểu và ràng buộc của dữ liệu đầu vào, còn FastAPI tự sinh tài liệu OpenAPI cho toàn bộ 82 điểm cuối. Việc kiểm tra dữ liệu đầu vào và tài liệu OpenAPI được sinh từ cùng một khai báo, đồng thời lỗi dữ liệu (HTTP 422) được phân biệt rõ với lỗi máy chủ; đây là căn cứ để chọn FastAPI thay cho một khung web không có kiểm tra kiểu tự động.'),
    ('p', 'Tầng dữ liệu của máy chủ dùng SQLAlchemy 2.0, lớp ánh xạ đối tượng – quan hệ (ORM) cho phép cùng một mô hình dữ liệu chạy trên SQLite khi phát triển, kiểm thử và trên PostgreSQL khi triển khai. PostgreSQL 16 là hệ quản trị cơ sở dữ liệu quan hệ [22] của môi trường triển khai. Hệ quan hệ được chọn thay cho cơ sở dữ liệu phi quan hệ vì dữ liệu sổ sách có quan hệ chặt và việc xử lý nguyên tử từng lô đồng bộ cần giao dịch ACID [24], như đã phân tích ở mục 2.4. Về xác thực, PyJWT phát hành và xác minh mã JWT [17], còn bcrypt băm mật khẩu. JWT không trạng thái được chọn thay cho phiên lưu trên máy chủ vì thiết bị có thể ngoại tuyến nhiều ngày, máy chủ không cần lưu phiên và dễ chạy nhiều tiến trình. Báo cáo PDF hỗ trợ tiếng Việt được sinh bằng fpdf2.'),
    ('p', 'Trang quản trị web được xây dựng bằng Next.js 16 (App Router) với React 19, TypeScript và Tailwind CSS 4. Next.js cung cấp sẵn định tuyến theo thư mục và bản dựng (build) tối ưu cho trình duyệt, nên không phải tự cấu hình như với một ứng dụng một trang; Tailwind CSS cho phép dùng chung bộ token thiết kế (màu, khoảng cách, phông chữ) với ứng dụng di động. Về kiến trúc, trang quản trị không có tầng dữ liệu riêng mà gọi cùng API với ứng dụng di động, nên quy tắc phân quyền chỉ cần hiện thực một lần ở máy chủ, đúng với nguyên tắc kiểm tra tại máy chủ ở mục 2.3.'),
    ('p', 'Việc kiểm thử dùng pytest, pytest-cov và httpx cho máy chủ, Jest cho ứng dụng di động, cùng ESLint và trình biên dịch TypeScript (tsc) để kiểm tra tĩnh. Danh mục giống, quy trình chăm sóc và phân bón được lưu thành các tệp JSON trong thư mục shared/data để dùng chung giữa các thành phần. Bảng 2.3 tổng hợp toàn bộ công nghệ theo thành phần kèm phiên bản; Bảng 2.4 đối chiếu từng lựa chọn với phương án thay thế phổ biến theo các ràng buộc của đề tài. Các căn cứ trong Bảng 2.4 là tiêu chí định tính về kiến trúc và vận hành, không phải kết quả đo đạc thực nghiệm.'),
    ('orig', 374),   # chú thích Bảng 2.3
    ('orig', 375),   # Bảng 2.3
    ('orig', 376),   # chú thích Bảng 2.4
    ('orig', 377),   # Bảng 2.4
]

